import type { TranslationPreset } from 'chrona-core/i18n';
import * as OpenAPI from 'chrona-openapi/i18n';
import * as UI from 'chrona-ui/i18n';
import * as Story from '@chrona/story/i18n';

const translations = {
  displayName: '繁體中文',
  'loading...(playground server select)': '載入中...',
  'No Variant(story controls)': '沒有變體',
  // ...
} satisfies Partial<UI.Translations & OpenAPI.Translations & Story.Translations>;

export function zhTW(): TranslationPreset<keyof typeof translations> {
  return {
    name: 'zh-TW',
    value: translations,
  };
}

